import 'package:flutter/material.dart';

import '../services/api_service.dart';

class InstructorScreen extends StatelessWidget {
  const InstructorScreen({required this.apiService, required this.user, required this.onLogout, required this.isDarkMode, required this.onThemeChanged, super.key});
  final ApiService apiService; final Map<String, dynamic> user; final VoidCallback onLogout; final bool isDarkMode; final ValueChanged<bool> onThemeChanged;
  @override Widget build(BuildContext context) => DefaultTabController(length: 6, child: Scaffold(appBar: AppBar(title: const Text('LearnFlow Instructor'), actions: [IconButton(onPressed: () async { await apiService.logout(); onLogout(); }, icon: const Icon(Icons.logout), tooltip: 'Sign out')], bottom: const TabBar(isScrollable: true, tabs: [Tab(icon: Icon(Icons.dashboard_outlined), text: 'Dashboard'), Tab(icon: Icon(Icons.add_box_outlined), text: 'Courses'), Tab(icon: Icon(Icons.video_library_outlined), text: 'Resources'), Tab(icon: Icon(Icons.assignment_outlined), text: 'Assignments'), Tab(icon: Icon(Icons.grading_outlined), text: 'Grading'), Tab(icon: Icon(Icons.people_outline), text: 'Students')])), body: TabBarView(children: [_Overview(apiService: apiService), _Courses(apiService: apiService, user: user), _Resources(apiService: apiService), _Assignments(apiService: apiService), _Grading(apiService: apiService), _Students(apiService: apiService)])));
}

class _Overview extends StatelessWidget { const _Overview({required this.apiService}); final ApiService apiService; @override Widget build(BuildContext context) => FutureBuilder<Map<String, dynamic>>(future: apiService.fetchDashboard('instructor'), builder: (context, snapshot) { if (snapshot.hasError) return const _State(icon: Icons.cloud_off, text: 'Dashboard unavailable. Reopen the tab to retry.'); if (!snapshot.hasData) return const Center(child: CircularProgressIndicator()); final stats = _maps(snapshot.data!['stats']); return RefreshIndicator(onRefresh: () async { await apiService.fetchDashboard('instructor'); }, child: ListView(padding: const EdgeInsets.all(16), children: [Text('Teaching overview', style: Theme.of(context).textTheme.headlineSmall), const SizedBox(height: 4), const Text('Keep courses, feedback, and learners moving forward.'), const SizedBox(height: 20), LayoutBuilder(builder: (context, constraints) { final columns = constraints.maxWidth > 650 ? 4 : 2; return GridView.builder(shrinkWrap: true, physics: const NeverScrollableScrollPhysics(), itemCount: stats.length, gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount: columns, crossAxisSpacing: 12, mainAxisSpacing: 12, childAspectRatio: 1.5), itemBuilder: (_, index) { final stat = stats[index]; return Card(child: Padding(padding: const EdgeInsets.all(14), child: Column(crossAxisAlignment: CrossAxisAlignment.start, mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [Text('${stat['label'] ?? ''}'), Text('${stat['value'] ?? ''}', style: Theme.of(context).textTheme.headlineMedium), Text('${stat['trend'] ?? ''}', style: TextStyle(color: Theme.of(context).colorScheme.primary))]))); }); })])); }); }

class _Courses extends StatefulWidget { const _Courses({required this.apiService, required this.user}); final ApiService apiService; final Map<String, dynamic> user; @override State<_Courses> createState() => _CoursesState(); }
class _CoursesState extends State<_Courses> { bool _loading = true; List<Map<String, dynamic>> _items = []; @override void initState() { super.initState(); _load(); } Future<void> _load() async { try { final items = await widget.apiService.fetchInstructorCourses(); if (mounted) setState(() => _items = items); } catch (error) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(error.toString()))); } finally { if (mounted) setState(() => _loading = false); } } Future<void> _create() async { final title = TextEditingController(); final description = TextEditingController(); final category = TextEditingController(text: 'General'); final result = await showDialog<bool>(context: context, builder: (context) => AlertDialog(title: const Text('Create course'), content: SingleChildScrollView(child: Column(children: [TextField(controller: title, decoration: const InputDecoration(labelText: 'Course title')), TextField(controller: description, minLines: 3, maxLines: 5, decoration: const InputDecoration(labelText: 'Description')), TextField(controller: category, decoration: const InputDecoration(labelText: 'Category'))])), actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Cancel')), FilledButton(onPressed: () => Navigator.pop(context, true), child: const Text('Create'))])); if (result != true || title.text.trim().isEmpty) return; try { await widget.apiService.createCourse({'title': title.text.trim(), 'description': description.text.trim(), 'category': category.text.trim(), 'status': 'Draft', 'level': 'Beginner'}); await _load(); } catch (error) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(error.toString()))); } finally { title.dispose(); description.dispose(); category.dispose(); } } @override Widget build(BuildContext context) => _loading ? const Center(child: CircularProgressIndicator()) : Scaffold(floatingActionButton: FloatingActionButton.extended(onPressed: _create, icon: const Icon(Icons.add), label: const Text('New course')), body: RefreshIndicator(onRefresh: _load, child: _items.isEmpty ? const _State(icon: Icons.menu_book_outlined, text: 'Create your first course.') : ListView(padding: const EdgeInsets.all(16), children: _items.map((item) => Card(child: ListTile(leading: const Icon(Icons.school_outlined), title: Text('${item['title'] ?? 'Untitled'}'), subtitle: Text('${item['category'] ?? ''} | ${item['level'] ?? ''}'), trailing: Text('${item['status'] ?? 'Draft'}')))).toList())); }

class _Resources extends StatelessWidget { const _Resources({required this.apiService}); final ApiService apiService; @override Widget build(BuildContext context) => _CoursePicker(apiService: apiService, title: 'Lesson and resource management', icon: Icons.video_library_outlined, load: (id) => apiService.fetchInstructorResources(id), actionLabel: 'Add resource', action: (id) => _resourceDialog(context, apiService, id)); }
class _Assignments extends StatelessWidget { const _Assignments({required this.apiService}); final ApiService apiService; @override Widget build(BuildContext context) => _CoursePicker(apiService: apiService, title: 'Assignment management', icon: Icons.assignment_outlined, load: (id) => apiService.fetchInstructorAssignments(id), actionLabel: 'Add assignment', action: (id) => _assignmentDialog(context, apiService, id)); }
class _CoursePicker extends StatefulWidget { const _CoursePicker({required this.apiService, required this.title, required this.icon, required this.load, required this.actionLabel, required this.action}); final ApiService apiService; final String title; final IconData icon; final Future<List<Map<String, dynamic>>> Function(int) load; final String actionLabel; final Future<void> Function(int) action; @override State<_CoursePicker> createState() => _CoursePickerState(); }
class _CoursePickerState extends State<_CoursePicker> { List<Map<String, dynamic>> _courses = []; List<Map<String, dynamic>> _items = []; int? _courseId; bool _loading = true; @override void initState() { super.initState(); _loadCourses(); } Future<void> _loadCourses() async { try { final courses = await widget.apiService.fetchInstructorCourses(); if (mounted) { setState(() { _courses = courses; _courseId = courses.isEmpty ? null : int.tryParse('${courses.first['id']}'); }); if (_courseId != null) _loadItems(); } } catch (_) {} finally { if (mounted) setState(() => _loading = false); } } Future<void> _loadItems() async { if (_courseId == null) return; setState(() => _loading = true); try { final items = await widget.load(_courseId!); if (mounted) setState(() => _items = items); } catch (error) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(error.toString()))); } finally { if (mounted) setState(() => _loading = false); } } @override Widget build(BuildContext context) => _loading && _courses.isEmpty ? const Center(child: CircularProgressIndicator()) : Column(children: [Padding(padding: const EdgeInsets.all(16), child: Row(children: [Expanded(child: DropdownButtonFormField<int>(value: _courseId, decoration: InputDecoration(labelText: widget.title, border: const OutlineInputBorder()), items: _courses.map((course) => DropdownMenuItem(value: int.tryParse('${course['id']}'), child: Text('${course['title'] ?? 'Course'}', overflow: TextOverflow.ellipsis))).toList(), onChanged: (value) { setState(() => _courseId = value); _loadItems(); })), const SizedBox(width: 10), if (_courseId != null) IconButton(onPressed: () => widget.action(_courseId!), icon: const Icon(Icons.add_circle_outline), tooltip: widget.actionLabel)])), Expanded(child: _loading ? const Center(child: CircularProgressIndicator()) : _items.isEmpty ? _State(icon: widget.icon, text: 'No items for this course yet.') : ListView(padding: const EdgeInsets.symmetric(horizontal: 16), children: _items.map((item) => Card(child: ListTile(title: Text('${item['title'] ?? 'Item'}'), subtitle: Text('${item['description'] ?? item['type'] ?? item['status'] ?? ''}')))).toList()))]); }

class _Grading extends StatefulWidget { const _Grading({required this.apiService}); final ApiService apiService; @override State<_Grading> createState() => _GradingState(); }
class _GradingState extends State<_Grading> { List<Map<String, dynamic>> _items = []; bool _loading = true; @override void initState() { super.initState(); _load(); } Future<void> _load() async { try { final items = await widget.apiService.fetchGradingSubmissions(); if (mounted) setState(() => _items = items); } catch (error) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(error.toString()))); } finally { if (mounted) setState(() => _loading = false); } } Future<void> _grade(Map<String, dynamic> item) async { final score = TextEditingController(); final feedback = TextEditingController(); final ok = await showDialog<bool>(context: context, builder: (context) => AlertDialog(title: Text('Grade ${item['student_email'] ?? 'submission'}'), content: Column(mainAxisSize: MainAxisSize.min, children: [TextField(controller: score, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText: 'Score (0-100)')), TextField(controller: feedback, decoration: const InputDecoration(labelText: 'Feedback'))]), actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Cancel')), FilledButton(onPressed: () => Navigator.pop(context, true), child: const Text('Save grade'))])); if (ok != true) return; try { await widget.apiService.gradeSubmission(int.parse('${item['id']}'), double.parse(score.text), feedback.text.trim()); await _load(); } catch (error) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(error.toString()))); } finally { score.dispose(); feedback.dispose(); } } @override Widget build(BuildContext context) => _loading ? const Center(child: CircularProgressIndicator()) : RefreshIndicator(onRefresh: _load, child: _items.isEmpty ? const _State(icon: Icons.grading_outlined, text: 'No pending submissions.') : ListView(padding: const EdgeInsets.all(16), children: _items.map((item) => Card(child: ListTile(title: Text('${item['assignment_title'] ?? 'Assignment'}'), subtitle: Text('${item['student_email'] ?? 'Student'}\nSubmitted ${item['submitted_at'] ?? ''}'), isThreeLine: true, trailing: FilledButton(onPressed: () => _grade(item), child: const Text('Grade')))).toList())); }
class _Students extends StatelessWidget { const _Students({required this.apiService}); final ApiService apiService; @override Widget build(BuildContext context) => _CoursePicker(apiService: apiService, title: 'Student management', icon: Icons.people_outline, load: (id) => apiService.fetchInstructorStudents(id), actionLabel: 'Refresh students', action: (id) async {}); }

Future<void> _resourceDialog(BuildContext context, ApiService api, int courseId) async { final title = TextEditingController(); final url = TextEditingController(); final ok = await showDialog<bool>(context: context, builder: (context) => AlertDialog(title: const Text('Add lesson/resource'), content: Column(mainAxisSize: MainAxisSize.min, children: [TextField(controller: title, decoration: const InputDecoration(labelText: 'Title')), TextField(controller: url, decoration: const InputDecoration(labelText: 'URL'))]), actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Cancel')), FilledButton(onPressed: () => Navigator.pop(context, true), child: const Text('Add'))])); if (ok == true && title.text.trim().isNotEmpty) await api.createResource({'course_id': courseId, 'title': title.text.trim(), 'file_url': url.text.trim(), 'type': 'Link'}); title.dispose(); url.dispose(); }
Future<void> _assignmentDialog(BuildContext context, ApiService api, int courseId) async { final title = TextEditingController(); final description = TextEditingController(); final ok = await showDialog<bool>(context: context, builder: (context) => AlertDialog(title: const Text('Create assignment'), content: Column(mainAxisSize: MainAxisSize.min, children: [TextField(controller: title, decoration: const InputDecoration(labelText: 'Title')), TextField(controller: description, decoration: const InputDecoration(labelText: 'Instructions'))]), actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Cancel')), FilledButton(onPressed: () => Navigator.pop(context, true), child: const Text('Create'))])); if (ok == true && title.text.trim().isNotEmpty) await api.createAssignment({'course_id': courseId, 'title': title.text.trim(), 'description': description.text.trim(), 'due_date': DateTime.now().add(const Duration(days: 7)).toIso8601String().substring(0, 10)}); title.dispose(); description.dispose(); }
List<Map<String, dynamic>> _maps(dynamic value) => value is List ? value.map((item) => Map<String, dynamic>.from(item as Map)).toList() : <Map<String, dynamic>>[];
class _State extends StatelessWidget { const _State({required this.icon, required this.text}); final IconData icon; final String text; @override Widget build(BuildContext context) => Center(child: Padding(padding: const EdgeInsets.all(32), child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [Icon(icon, size: 48, color: Theme.of(context).colorScheme.primary), const SizedBox(height: 12), Text(text, textAlign: TextAlign.center)]))); }
